/* From Uiverse.io by AKAspidey01 - Tags: button, add */
.__UIV_SCOPE__ .first-button {
  background: rgb(115, 15, 209);
  color: #fff;
  border: none;
  font-weight: 700;
  font-size: 1em;
  min-height: 60px;
  width: 200px;
  gap: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition-duration: 0.6s;
}

.__UIV_SCOPE__ .main-section {
  display: flex;
  flex-direction: column;
  height: 60px;
  overflow: hidden;
  align-items: flex-start;
}

.__UIV_SCOPE__ .main-section:hover .second-button, .__UIV_SCOPE__ .main-section:hover .first-button {
  transform: translateY(-60px);
}

.__UIV_SCOPE__ .second-button {
  background: rgb(209, 15, 57);
  color: #fff;
  border: none;
  font-weight: 700;
  font-size: 1em;
  min-height: 60px;
  width: 200px;
  gap: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition-duration: 0.6s;
}
